/**
 * Wallet <-> relayer parity: the delegations the WALLET's own builder produces (fixtures/wallet-delegation-parity.json,
 * regenerated by wallet/scripts/gen-delegation-fixture.ts and checked in CI) must be accepted or refused by the RELAYER's
 * validator exactly as the fixture says. The two sides are written separately, so this is the test that catches a
 * disagreement on the redeemer lock's terms encoding.
 *   npm run test:walletparity
 */
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";

process.env.RPC_URL ??= "http://127.0.0.1:9";
process.env.CHAIN_ID ??= "137";
process.env.STATE_DIR = "";
process.env.RELAYER_PRIVATE_KEY ??= "0x59c6995e998f97a5a0044966f0945389dc9e86dae88c7a8412f4603b6b78690d";
process.env.DELEGATION_MANAGER ??= "0xdb9B1e94B5b69Df7e401DDbedE43491141047dB3";
process.env.DELEGATOR_IMPLEMENTATION ??= "0x63c0c19a282a1B52b07dD5a65b58948A07DAE32B";
process.env.FEE_MARKET_REGISTRY ??= "0x57e6742610229c7Ce09df3028471397DaaE6B9f4";
process.env.REDEEMER_RESTRICTION_ENFORCER ??= "0x5C75d7ee6d3d27634bec15e96538e794F9c7053b";
process.env.SPONSOR_ID = "1";

const { validatePinnedDelegation } = await import("../src/services/batchValidation.js");
const { relayerAddress } = await import("../src/lib/clients.js");
const { config } = await import("../src/config.js");

const fixture = JSON.parse(readFileSync(new URL("../fixtures/wallet-delegation-parity.json", import.meta.url), "utf8")) as {
  now: number; relayer: string; registry: string; sponsorId: number;
  cases: { name: string; expect: "accepted" | "rejected"; delegation: Record<string, unknown>; executionCallData: `0x${string}` }[];
};

let passed = 0, total = 0;
function test(name: string, fn: () => void) {
  total++;
  try { fn(); passed++; console.log(`  ✓ ${name}`); } catch (e) { console.error(`  ✗ ${name}\n    ${(e as Error).message}`); process.exitCode = 1; }
}

test("the fixture was made for this relayer, registry and sponsor", () => {
  assert.equal(fixture.relayer.toLowerCase(), relayerAddress.toLowerCase());
  assert.equal(fixture.registry.toLowerCase(), config.feeMarketRegistry.toLowerCase());
  assert.equal(BigInt(fixture.sponsorId), config.sponsorId);
});
for (const c of fixture.cases) {
  test(`wallet delegation: ${c.name} is ${c.expect}`, () => {
    const r = validatePinnedDelegation([c.delegation] as never, c.executionCallData, undefined, fixture.now);
    assert.equal(r.ok, c.expect === "accepted", c.expect === "accepted" ? (r as { reason?: string }).reason : "the relayer accepted something it must refuse");
  });
}
test("the fixture covers both locks and both outcomes", () => {
  assert.ok(fixture.cases.some((c) => c.expect === "accepted") && fixture.cases.some((c) => c.expect === "rejected"));
  assert.ok(fixture.cases.length >= 5);
});

console.log(`\n${passed}/${total} passed`);
if (passed !== total) process.exit(1);
